import org.assertj.core.api.Assertions;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;

public class FileProcessingServiceTest {

    public void testProcessFileHandlesInvalidPath(Path tempDir) {
        Path nonExistentFile = tempDir.resolve("missing.txt");

        // AssertJ Exception Handling & NIO integration
        Assertions.assertThatThrownBy(() -> Files.readString(nonExistentFile))
            .isInstanceOf(IOException.class)
            .hasMessageContaining(nonExistentFile.toString());

        Path validFile = tempDir.resolve("config.properties");

        // AssertJ Fluent NIO Path Assertions
        Assertions.assertThat(validFile)
            .doesNotExist()
            .hasParent(tempDir);
    }
}
